const catalogPageSize=80;
let catalogResults=[],catalogPage=1;

function drawCatalog(a){
 const changed=a.length!==catalogResults.length||a.some((event,index)=>event!==catalogResults[index]);
 if(changed)catalogPage=1;
 catalogResults=a;
 $('#catalog-summary').textContent=`Найдено ${a.length} из ${EVENTS.length} записей · ${a.filter(e=>e.start).length} с указанными датами. Поиск и фильтры работают по всей базе.`;
 drawCatalogPage();
 if(changed)$('#catalog-table-container').scrollTop=0;
}

function drawCatalogPage(){
 const totalPages=Math.max(1,Math.ceil(catalogResults.length/catalogPageSize));
 const offset=(catalogPage-1)*catalogPageSize;
 const rows=catalogResults.slice(offset,offset+catalogPageSize);
 const picker=$('#catalog-page');
 if(picker.options.length!==totalPages){
  picker.replaceChildren(...Array.from({length:totalPages},(_,index)=>new Option(String(index+1),String(index+1))));
 }
 picker.value=String(catalogPage);
 $('#catalog-pagination').hidden=totalPages===1;
 $('#catalog-prev').disabled=catalogPage===1;
 $('#catalog-next').disabled=catalogPage===totalPages;
 $('#catalog-page-range').textContent=`${offset+1}–${offset+rows.length} / ${catalogResults.length}`;
 $('#catalog-table-container').innerHTML=rows.length?`<table class="catalog-table"><caption class="sr-only">Строк на странице: ${rows.length}</caption><thead><tr><th scope="col">Мероприятие / дисциплина</th><th scope="col">Даты и срок заявки</th><th scope="col">Страна / город</th><th scope="col">Дети и формат</th><th scope="col">Стоимость / проверка</th><th scope="col">Открыть</th></tr></thead><tbody>${rows.map(e=>`<tr data-id="${esc(e.id)}" class="${excluded(e)?'catalog-restricted':''}" ${DIRECTIONS.attributes(e.themes)}><td data-label="Мероприятие"><span class="catalog-id">${esc(e.id)} · ${esc(e.block)} · ${esc(e.priority.split(' — ')[0])}</span><button class="catalog-title" data-open="${esc(e.id)}">${esc(e.title)}</button>${window.bestBadge('event',e.id)}${DIRECTIONS.chips(e.themes)}<span class="catalog-detail">${esc(scopeLabels[e.scope]||e.scope)}${excluded(e)?' · Есть ограничение':''}</span></td><td data-label="Даты"><b>${esc(dateText(e))}</b>${e.deadline?`<span class="catalog-detail">${esc(e.deadline_label||'Регистрация')}: ${esc(shortDate(e.deadline))}</span>`:''}<span class="catalog-detail">${esc(e.date_status)}</span></td><td data-label="Место"><b>${esc(e.country)}</b><span class="catalog-detail">${esc(e.city||e.region)}</span></td><td data-label="Дети / формат"><div class="kid-chips">${kidChip(e,'mat','Матвей')}${kidChip(e,'osc','Оскар')}</div><span class="catalog-detail">${esc(participationLabels[e.participation]||e.participation)}</span><span class="catalog-detail">${esc(e.age)}</span></td><td data-label="Стоимость / проверка"><span>${esc(e.cost)}</span><span class="catalog-evidence">${esc(evidenceLabels[e.evidence_level]||'Проверка указана в карточке')}</span></td><td data-label="Действия"><button class="button secondary catalog-open" data-open="${esc(e.id)}">Подробнее</button><a class="catalog-source" href="${esc(e.source)}" target="_blank" rel="noopener">Источник</a></td></tr>`).join('')}</tbody></table>`:empty();
}

function showCatalogPage(page){
 const totalPages=Math.ceil(catalogResults.length/catalogPageSize);
 if(!Number.isInteger(page)||page<1||page>totalPages||page===catalogPage)return;
 catalogPage=page;
 drawCatalogPage();
 $('#catalog-table-container').scrollTop=0;
}
$('#catalog-prev').onclick=()=>showCatalogPage(catalogPage-1);
$('#catalog-next').onclick=()=>showCatalogPage(catalogPage+1);
$('#catalog-page').onchange=event=>showCatalogPage(Number(event.target.value));

function setView(view){if(!labels[view])return;state.view=view;state.limit=12;if(view==='catalog')state.excluded=true;if(['exhibitions','camps'].includes(view))Object.assign(state,{best:false,languageMode:'',campProjects:false,league:'',block:'',query:'',kid:'',region:'',country:'',theme:'',language:'',scope:'',participation:'',admission:'',evidence:'',visitorPolicy:'',dates:'',online:false,priority:false,excluded:true,sort:'date'});if(view!=='exhibitions')state.visitorPolicy='';if(view!=='catalog')state.campProjects=false;$('.sidebar').classList.remove('open');$('#menu-button').setAttribute('aria-expanded','false');atlasLinks.navigate(view);render()}
function reset(){catalogPage=1;Object.assign(state,{routeIsos:[],best:false,languageMode:'',campProjects:false,league:'',block:'',query:'',kid:'',region:'',country:'',theme:'',language:'',scope:'',participation:'',admission:'',evidence:'',visitorPolicy:'',dates:'',online:false,priority:false,excluded:['catalog','exhibitions','camps'].includes(state.view),limit:12,day:''});render()}
function notify(text){$('#toast').textContent=text;$('#toast').hidden=false;clearTimeout(notify.timeout);notify.timeout=setTimeout(()=>$('#toast').hidden=true,3200)}
function toggleFavorite(id){favoriteIds.has(id)?favoriteIds.delete(id):favoriteIds.add(id);try{localStorage.setItem('stemAtlasFavorites.v1',JSON.stringify([...favoriteIds]))}catch{notify('Сохранение доступно только до закрытия этой страницы.')};render();if($('#event-dialog').open)openEvent(id,false)}
function toggleCompare(id){if(state.compare.has(id))state.compare.delete(id);else if(state.compare.size<3)state.compare.add(id);else{notify('Для удобного сравнения выберите не больше трёх вариантов.');return}render()}
function updateCompare(){$('#compare-tray').hidden=!state.compare.size;$('#compare-count').textContent=`Выбрано ${state.compare.size} из 3`;$('#compare-open').disabled=state.compare.size<2}
function programmeSchedule(e){
 const timezoneName=zone=>({'Europe/London':'Лондон','Australia/Sydney':'Канберра','Asia/Singapore':'Сингапур','Africa/Johannesburg':'Южная Африка','America/Argentina/Buenos_Aires':'Буэнос-Айрес'}[zone]||zone);
 let out='';
 if(e.sessions?.length)out+=`<div class="dialog-block"><h3>Расписание по дням</h3><p class="schedule-note">Время указано для места проведения.</p><ul class="programme-sessions">${e.sessions.map(day=>`<li><strong>${esc(shortDate(day.date))}</strong><span>${esc(day.topic)}${day.start_time?`<small>${esc(day.start_time)}–${esc(day.end_time)} · ${esc(timezoneName(day.timezone))}</small>`:''}${day.time_note?`<small>${esc(day.time_note)}</small>`:''}</span></li>`).join('')}</ul></div>`;
 if(e.planned_windows?.length)out+=`<div class="dialog-block"><h3>Опубликованные окна каникул</h3><p class="schedule-note">Отдельные дни занятий ещё уточняются. Эти периоды не добавлены в календарь.</p><ul class="programme-sessions">${e.planned_windows.map(w=>`<li><strong>${esc(w.label)}</strong><span>${esc(shortDate(w.start))}–${esc(shortDate(w.end))}<small>${esc(w.status)}</small></span></li>`).join('')}</ul></div>`;
 return out;
}
function exhibitionHighlights(event) {
  const highlights = event.highlights;
  return Array.isArray(highlights) ? highlights.join(' · ') : highlights || '';
}

function exhibitionPublicDay(day) {
  if (typeof day === 'string') return shortDate(day);
  const date = shortDate(day.date);
  return day.start_time && day.end_time ? `${date} · ${day.start_time}–${day.end_time}` : date;
}

function exhibitionCalendarBounds(event) {
  const day = event.public_days?.[0];
  if (event.start === event.end && event.public_days?.length === 1 && day?.date === event.start &&
      day.ical_timed && day.start_utc && day.end_utc) {
    const compact = instant => new Date(instant).toISOString().replace(/[-:]/g, '').replace(/\.\d{3}/, '');
    return [compact(day.start_utc), compact(day.end_utc), true];
  }
  return [event.start, addDays(event.end, 1), false];
}

function exhibitionDetails(e){if(!e.exhibition_tier)return '';return `<div class="dialog-block exhibition-admission"><h3>Посещение с детьми и взрослый вход</h3>${visitorBadge(e)}<p>${esc(e.visitor_policy_note)}</p><p><b>Взрослый посетитель:</b> ${esc(e.adult_entry)}</p>${e.child_entry?`<p><b>Детский вход:</b> ${esc(e.child_entry)}</p>`:''}${e.public_days?.length?`<p><b>Публичный день:</b> ${esc(e.public_days.map(exhibitionPublicDay).join(', '))}. Возрастной допуск проверить отдельно.</p>`:''}</div><div class="dialog-block"><h3>Что увидеть и какие компании</h3><p>${esc(exhibitionHighlights(e))}</p><p>${esc(e.exhibitor_note)}</p>${e.exhibitor_directory_url?`<a class="text-button" href="${esc(e.exhibitor_directory_url)}" target="_blank" rel="noopener">Каталог / программа организатора ↗</a>`:''}<p class="schedule-note">Выбирайте год издания. Упоминание докладчика, прошлогоднего участника или прогноз не подтверждает будущий стенд.</p></div>`}
function relatedEventLinks(event) {
  const ids = new Set([event.canonical_event_id, ...(event.related_ids || [])]);
  ids.delete(undefined);
  ids.delete(event.id);
  const related = Array.from(ids, id => EVENTS.find(row => row.id === id)).filter(Boolean);
  if (!related.length) return '';
  const title = 'Связанные карточки';
  const links = related.map(row =>
    `<li><button type="button" class="catalog-title" data-open="${esc(row.id)}">${esc(row.title)}</button></li>`
  ).join('');
  return `<div class="dialog-block"><h3>${title}</h3><ul class="reference-links">${links}</ul></div>`;
}

function openEvent(id,show=true){const e=EVENTS.find(e=>e.id===id);if(!e)return;const fav=favoriteIds.has(id);$('#dialog-content').innerHTML=`<header class="dialog-header"><span class="section-kicker">${esc(e.block)} · ${esc(e.id)}</span><h2 id="event-title">${esc(e.title)}</h2>${DIRECTIONS.chips(e.themes)}<p>${esc(e.country)}${e.city?' · '+esc(e.city):''}${e.venue&&e.venue!==e.city?' · '+esc(e.venue):''}</p><div class="kid-chips">${kidChip(e,'mat','Матвей')}${kidChip(e,'osc','Оскар')}</div></header><div class="dialog-body"><div class="dialog-data"><div><label>ДАТА И ДЕДЛАЙН</label><p>${esc(dateText(e))}<br>${esc(e.date_status)}${e.registration_status?"<br><strong>"+esc(e.registration_status)+"</strong>":""}${e.deadline?'<br>'+esc(e.deadline_label||'Дедлайн')+': '+shortDate(e.deadline)+(e.deadline_note?'<br>'+esc(e.deadline_note):''):''}</p></div><div><label>ВОЗРАСТ И КОМАНДА</label><p>${esc(e.age)}<br>${esc(e.format)}</p></div><div><label>ТЕХНИКА</label><p>${esc(e.gear)}</p></div><div><label>ЯЗЫК И СТОИМОСТЬ</label><p>${esc(e.language)}${campLanguageDetail(e)}<br>${esc(e.cost)}</p></div></div>${programmeSchedule(e)}${exhibitionDetails(e)}<div class="dialog-block"><h3>Как попасть</h3>${e.admission_kind?`<p class="entry-kind">${esc(admissionLabels[e.admission_kind])}</p>`:""}<p>${esc(e.entry)}</p></div><div class="dialog-next"><h3>Следующий шаг</h3><p>${esc(e.action)}</p></div><div class="dialog-block"><h3>Масштаб и приоритет</h3><p>${esc(scopeLabels[e.scope])} · ${esc(e.priority)}<br>${esc(e.importance_reason)}</p></div><div class="dialog-block"><h3>Тема и формат</h3><p>${esc(e.themes.map(t=>DIRECTIONS.labels[t]||t).join(" · "))}<br>${esc(participationLabels[e.participation])}</p></div><div class="dialog-block"><h3>Что даст участие</h3><p>${esc(e.reward)}<br>${esc(e.level)}</p></div><div class="dialog-block"><h3>Что ещё проверить</h3><p>${esc(e.note)}<br>${esc(e.language_certainty)}</p></div><div class="proof-line"><b>Основание проверки · ${shortDate(e.checked)}</b>${e.evidence_level?esc(evidenceLabels[e.evidence_level])+". ":""}${esc(e.proof)}<br>Матвей: ${esc(e.mat)}. Оскар: ${esc(e.osc)}.<br>Состояние по исходным данным: ${esc(e.status)}. Сохранение в планы не изменяет статус заявки.</div>${e.references?.length?`<div class="dialog-block"><h3>Регламенты и связанные источники</h3><ul class="reference-links">${e.references.filter(r=>/^https?:\/\//.test(r.url)).map(r=>`<li><a href="${esc(r.url)}" target="_blank" rel="noopener">${esc(r.label)} ↗</a></li>`).join("")}</ul></div>`:""}${relatedEventLinks(e)}${campDossierLink(e)}<div class="dialog-actions"><a class="button primary" href="${esc(e.source)}" target="_blank" rel="noopener">Официальная страница ${icon('arrow')}</a><button class="button secondary" data-favorite="${id}" aria-pressed="${fav}">${icon('heart')}${fav?'Убрать из планов':'В планы семьи'}</button>${e.start||e.deadline?`<button class="button secondary" data-export="${id}" ${e.exhibition_tier?'data-export-visit="true"':''}>${icon('calendar')}${e.exhibition_tier?'Даты выставки · допуск отдельно':'Скачать даты / сроки'}</button>`:''}</div></div>`;$('#event-dialog').setAttribute('aria-labelledby','event-title');
  $('#event-dialog').dataset.eventId=e.id;
  $('#dialog-content .dialog-actions').append($('#share-event-template').content.cloneNode(true));
  if(show&&!$('#event-dialog').open)$('#event-dialog').showModal();
  else if (show) {
    const title = $('#event-title');
    title.tabIndex = -1;
    title.focus();
  }
  return true;
}
function openComparison(){const a=[...state.compare].map(id=>EVENTS.find(e=>e.id===id));if(a.length<2)return;const keys=[['Когда','date'],['Возраст / класс','age'],['Матвей','mat'],['Оскар','osc'],['Команда','format'],['Путь входа','entry'],['Техника','gear'],['Язык','language'],['Стоимость','cost'],['Результат','reward'],['Следующий шаг','action']];$('#compare-content').innerHTML=`<div class="compare-grid" style="--cols:${a.length}">${a.map(e=>`<article class="compare-column"><h3>${esc(e.title)}</h3>${keys.map(([label,k])=>`<div class="compare-field"><small>${label}</small><p>${esc(k==='date'?dateText(e):e[k])}</p></div>`).join('')}<div class="compare-field"><a href="${esc(e.source)}" target="_blank" rel="noopener">Официальный источник ↗</a></div></article>`).join('')}</div>`;$('#compare-dialog').showModal()}
function calendarEntries(a){const list=[];for(const e of a){if(e.start&&e.date_scope==='session_days'){for(const session of e.sessions)list.push({e,date:session.date,end:session.date,label:e.title+' · '+session.start_time+'–'+session.end_time+' '+session.timezone,kind:classes(e)})}else if(e.start)list.push({e,date:e.start,end:e.end,label:(e.date_status==='Анонсировано'?'Анонс · проведение уточнить · ':'')+(e.date_scope==='judging'?'Виртуальная защита проектов: ':e.date_scope==='assessment_window'?'Окно прохождения конкурса: ':e.date_scope==='submission_window'?'Окно подачи результатов: ':e.event_type==='League'?'Период лиги: ':e.date_scope==='assigned_day_window'?'Окно · один назначенный день: ':e.date_scope==='festival_window'?'Дни мероприятия: ':'')+(shortTitles[e.id]||e.title),kind:classes(e)});if(e.deadline)list.push({e,date:e.deadline,end:e.deadline,label:(e.deadline_label||'Дедлайн')+': '+(shortTitles[e.id]||e.title),kind:'deadline'})}if(a.some(e=>e.id==='C001'))list.push({e:EVENTS.find(e=>e.id==='C001'),date:'2026-09-30',end:'2026-09-30',label:'Проверить форму LUVÁ',kind:'deadline'});return list}
