$('#menu-button').onclick=()=>{const on=$('.sidebar').classList.toggle('open');$('#menu-button').setAttribute('aria-expanded',String(on))};$('#reset-button').onclick=reset;$('#load-more').onclick=()=>{state.limit+=12;render()};$('#nearby-button').onclick=()=>{Object.assign(state,{region:'latam',dates:'soon',view:'explore',limit:12});render();$('.workspace').scrollIntoView({behavior:'smooth'})};$('#urgent-button').onclick=()=>{reset();state.priority=true;state.view='explore';render();$('.workspace').scrollIntoView({behavior:'smooth'})};$('#export-filtered').onclick=()=>downloadICS(state.view==='saved'?filtered().filter(e=>favoriteIds.has(e.id)):filtered(),state.view==='exhibitions');$('#compare-open').onclick=openComparison;$('#compare-clear').onclick=()=>{state.compare.clear();render()};$('#map-reset').onclick=()=>{state.country='';render()};$('#country-search').oninput=e=>{state.countryQuery=e.target.value;state.countryLimit=24;drawCountries()};$('#more-countries').onclick=()=>{state.countryLimit+=24;drawCountries()};$('#clear-day').onclick=()=>{state.day='';drawCalendar(filtered())};function moveMonth(n){const [y,m]=state.month.split('-').map(Number);state.month=new Date(Date.UTC(y,m-1+n,1,12)).toISOString().slice(0,7);state.day='';drawCalendar(filtered())}$('#prev-month').onclick=()=>moveMonth(-1);$('#next-month').onclick=()=>moveMonth(1);$('#current-month').onclick=()=>{state.month=TODAY.slice(0,7);state.day='';drawCalendar(filtered())};
for(const dialog of $$('dialog'))dialog.addEventListener('click',e=>{if(e.target===dialog&&(()=>{const r=dialog.getBoundingClientRect();return e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom})())dialog.close()});
const available=[...COUNTRIES].sort((a,b)=>a.country.localeCompare(b.country));$('#country-filter').innerHTML='<option value="">Все страны</option>'+available.map(c=>`<option value="${c.iso}">${esc(c.country)}</option>`).join('');
$('#catalog-reset').onclick=()=>{reset();state.excluded=true;setView('catalog')};
const atlasLinks=window.initAtlasLinks(state,DATA.league_guide.profiles);
function applyLocationRoute(){window.syncFamilyTrackFromURL?.();const view=location.hash.slice(1);if(['taiwan','local','southamerica','europe','europe-north','europe-south','southeastasia','asia-english','eastasia','africa','middleeast'].includes(view)){state.view='about';auditState.tab=view}else if(labels[view])state.view=view;if(['catalog','exhibitions','camps'].includes(state.view))state.excluded=true;if(state.view==='camps'){state.block='';state.league='';state.campProjects=false};if(state.view==='exhibitions')state.sort='date';if(atlasLinks.restore(view))catalogPage=1;render();atlasLinks.openSharedEvent(view,openEvent,notify);if(['taiwan','local','southamerica','europe','europe-north','europe-south','southeastasia','asia-english','eastasia','africa','middleeast'].includes(view))requestAnimationFrame(()=>$('.taiwan-intro')?.scrollIntoView({block:'start'}))}icons();applyLocationRoute();window.addEventListener('hashchange',applyLocationRoute);window.addEventListener('popstate',applyLocationRoute);let timer;window.addEventListener('resize',()=>{clearTimeout(timer);timer=setTimeout(()=>{if(state.view==='map')drawMap(filtered());if(state.view==='explore')drawGlobe()},100)});
